import { useCallback, useRef, useState } from 'react';
import { createGame, MAX_SEED } from '../deal.ts';
import type { GameState, Size } from '../model.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { activateCard, advanceGame, formatTime, isWon } from '../transitions.ts';
import { readPreferences, savePreferences } from './storage.ts';
import { useClock } from './useClock.ts';
import { useAnnouncement } from './useAnnouncement.ts';

function freshGame(size: Size, previousSeed = 0): GameState {
  const random = new Uint32Array(1);
  crypto.getRandomValues(random);
  let seed = (random[0] ?? 0) % MAX_SEED + 1;
  if (seed === previousSeed) seed = seed % MAX_SEED + 1;
  const game = createGame(`np1-${size}-${seed}`);
  if (!game) throw new Error('Unable to create deal');
  return game;
}
interface SessionState { game: GameState; paused: boolean; generation: number; celebrate: boolean }

export function useSession() {
  const [preferences, setPreferences] = useState(readPreferences);
  const preferencesRef = useRef(preferences);
  const [session, setSession] = useState<SessionState>(() => ({
    game: freshGame(preferences.size), paused: false, generation: 0, celebrate: false,
  }));
  const current = useRef(session);
  const { announcement, announce } = useAnnouncement();
  const commit = useCallback((next: SessionState) => {
    current.current = next;
    setSession(next);
  }, []);
  const advance = useCallback((milliseconds: number) => {
    const state = current.current;
    if (state.paused) return;
    const game = advanceGame(state.game, milliseconds);
    if (game !== state.game) commit({ ...state, game });
  }, [commit]);
  const clock = useClock(advance, session.generation);
  const save = (size: Size, best?: number) => {
    const next = { size, bests: { ...preferencesRef.current.bests } };
    if (best !== undefined) next.bests[size] = Math.min(best, next.bests[size] ?? Infinity);
    preferencesRef.current = next;
    setPreferences(next);
    savePreferences(next);
  };
  const replace = (game: GameState, imported = false) => {
    clock.reset();
    commit({ game, paused: imported && !isWon(game), generation: current.current.generation + 1, celebrate: false });
    save(game.board.size);
  };
  const activate = (index: number) => {
    clock.flush();
    const before = current.current;
    if (before.paused) return;
    const game = activateCard(before.game, index);
    if (game === before.game) return;
    const won = isWon(game);
    commit({ ...before, game, celebrate: won });
    if (before.game.selection.kind !== 'one' || game.selection.kind === 'one') return;
    if (won) {
      save(game.board.size, game.moves);
      announce(`Pair found. All pairs found in ${game.moves} moves and ${formatTime(game.elapsedMs)}.`);
    } else if (game.selection.kind === 'mismatch') {
      announce('No match. Cards close after a short pause.');
    } else {
      const count = game.matched.length / 2;
      announce(`Pair found. ${count} ${count === 1 ? 'pair' : 'pairs'} matched.`);
    }
  };
  const loadBoard = (draft: string) => {
    const game = createGame(draft.trim());
    if (!game) { announce('Invalid board code.'); return false; }
    replace(game);
    return true;
  };
  const loadSnapshot = (draft: string) => {
    const game = decodeSnapshot(draft);
    if (!game) { announce('Invalid snapshot.'); return null; }
    replace(game, true);
    const message = isWon(game) ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.';
    announce(message);
    return message;
  };
  return {
    ...session, announcement, best: preferences.bests[session.game.board.size], activate, loadBoard, loadSnapshot,
    newGame: (size = current.current.game.board.size) => replace(freshGame(size, current.current.game.board.seed)),
    restart: () => { const game = createGame(current.current.game.board.code); if (game) replace(game); },
    resume: () => { clock.flush(); commit({ ...current.current, paused: false }); },
    exportSnapshot: () => { clock.flush(); return encodeSnapshot(current.current.game); },
  };
}
import { useCallback, useEffect, useRef } from 'react';

export function useClock(advance: (milliseconds: number) => void, generation: number) {
  const last = useRef(performance.now());
  const visible = useRef(!document.hidden);
  const epoch = useRef(0);
  const flush = useCallback(() => {
    const now = performance.now();
    const delta = Math.max(0, now - last.current);
    last.current = now;
    if (visible.current) advance(delta);
  }, [advance]);
  const reset = useCallback(() => {
    epoch.current++;
    last.current = performance.now();
    visible.current = !document.hidden;
  }, []);
  useEffect(() => {
    let cancelled = false;
    const token = epoch.current;
    const tick = () => { if (!cancelled && token === epoch.current) flush(); };
    const visibility = () => {
      if (cancelled || token !== epoch.current) return;
      flush();
      visible.current = !document.hidden;
    };
    const timer = window.setInterval(tick, 32);
    document.addEventListener('visibilitychange', visibility);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
      document.removeEventListener('visibilitychange', visibility);
    };
  }, [flush, generation]);
  return { flush, reset };
}
import { useCallback, useEffect, useRef, useState } from 'react';

// Clearing between events gives identical consecutive messages their own live update.
export function useAnnouncement() {
  const [text, setText] = useState('');
  const pending = useRef<string[]>([]);
  const busy = useRef(false);
  const timer = useRef<number | undefined>(undefined);
  const announce = useCallback((message: string) => {
    pending.current.push(message);
    if (busy.current) return;
    busy.current = true;
    const deliver = () => {
      if (!pending.current.length) { busy.current = false; return; }
      setText('');
      timer.current = window.setTimeout(() => {
        setText(pending.current.shift() ?? '');
        timer.current = window.setTimeout(deliver, 180);
      }, 60);
    };
    deliver();
  }, []);
  useEffect(() => () => window.clearTimeout(timer.current), []);
  return { announcement: text, announce };
}
import { useImperativeHandle, useRef, useState } from 'react';
import type { CSSProperties, KeyboardEvent, Ref } from 'react';
import type { GameState } from '../model.ts';
import { Face } from './Face.tsx';
import { faceParts } from './faces.ts';
import './Board.css';

export interface BoardHandle { focus: () => void }
interface BoardProps { game: GameState; paused: boolean; activate: (index: number) => void; ref: Ref<BoardHandle> }

export function Board({ game, paused, activate, ref }: BoardProps) {
  const [tabStop, setTabStop] = useState(0);
  const buttons = useRef(new Map<number, HTMLButtonElement>());
  useImperativeHandle(ref, () => ({ focus: () => buttons.current.get(tabStop)?.focus() }), [tabStop]);
  const onKey = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const size = game.board.size;
    let next = index;
    switch (event.key) {
      case 'ArrowLeft': if (index % size > 0) next--; break;
      case 'ArrowRight': if (index % size < size - 1) next++; break;
      case 'ArrowUp': if (index >= size) next -= size; break;
      case 'ArrowDown': if (index < size * (size - 1)) next += size; break;
      default: return;
    }
    event.preventDefault();
    buttons.current.get(next)?.focus();
  };
  const style: CSSProperties & { '--columns': number; '--gaps': string } = {
    '--columns': game.board.size, '--gaps': `${(game.board.size - 1) * 6}px`,
  };
  return <div className="board-scroll" aria-label="Card board" role="group">
    <div className="board" style={style}>
      {game.deck.map((face, index) => {
        const matched = game.matched.includes(index);
        const selected = game.selection.kind === 'one' ? game.selection.index === index
          : game.selection.kind === 'mismatch' && (game.selection.first === index || game.selection.second === index);
        const revealed = matched || selected;
        const position = `Row ${Math.floor(index / game.board.size) + 1}, column ${index % game.board.size + 1}`;
        const state = matched ? 'matched' : revealed ? 'revealed' : 'closed';
        return <button key={index} type="button" className={`card ${state}`} tabIndex={tabStop === index ? 0 : -1}
          ref={node => { if (node) buttons.current.set(index, node); else buttons.current.delete(index); }}
          aria-label={`${position}, ${revealed ? `${faceParts(face).name}, ` : ''}${state}`}
          aria-disabled={matched || paused || game.selection.kind === 'mismatch'}
          onFocus={event => {
            setTabStop(index);
            event.currentTarget.scrollIntoView({ block: 'nearest', inline: 'nearest' });
          }}
          onKeyDown={event => onKey(event, index)} onClick={event => {
            if (event.detail !== 0 || !(event.altKey || event.ctrlKey || event.metaKey || event.shiftKey)) activate(index);
          }}>
          {revealed ? <Face id={face} /> : <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false">
            <path d="M50 39 61 50 50 61 39 50Z" fill="none" stroke="currentColor" strokeWidth="3" />
          </svg>}
          {matched && <span className="check" aria-hidden="true">✓</span>}
        </button>;
      })}
    </div>
  </div>;
}
import { useState } from 'react';
import './Controls.css';

interface ReproductionProps {
  code: string;
  generation: number;
  loadBoard: (text: string) => boolean;
  loadSnapshot: (text: string) => string | null;
  exportSnapshot: () => string;
}
export function Reproduction({ code, generation, loadBoard, loadSnapshot, exportSnapshot }: ReproductionProps) {
  const [draft, setDraft] = useState({ generation, text: code });
  const [snapshot, setSnapshot] = useState('');
  const [status, setStatus] = useState('');
  if (draft.generation !== generation) setDraft({ generation, text: code });
  return <details className="reproduction">
    <summary>Reproduce a game</summary>
    <div className="reproduction-content">
      <p className="help">A board code repeats a deal. A snapshot saves your progress.</p>
      <label htmlFor="board-code">Board code</label>
      <div className="code-controls">
        <input id="board-code" value={draft.text} maxLength={32} spellCheck={false}
          onChange={event => setDraft({ generation, text: event.target.value })} />
        <button type="button" onClick={() => {
          if (loadBoard(draft.text)) setStatus('');
          else setStatus('Invalid board code.');
        }}>Load board</button>
      </div>
      <label htmlFor="snapshot-json">Snapshot JSON</label>
      <textarea id="snapshot-json" value={snapshot} rows={6} maxLength={65536} spellCheck={false}
        onChange={event => setSnapshot(event.target.value)} />
      <div className="snapshot-controls">
        <button type="button" onClick={() => { setSnapshot(exportSnapshot()); setStatus(''); }}>Export snapshot</button>
        <button type="button" onClick={() => setStatus(loadSnapshot(snapshot) ?? 'Invalid snapshot.')}>Load snapshot</button>
      </div>
      {status && <p className="load-status">{status}</p>}
    </div>
  </details>;
}

